use core.files as files
use core.process as process
use core.text as text


struct Parent {
    section: String
    parent: String
}

struct Field {
    section: String
    key: String
    value: String
}

fn parent_for(parents: [Parent], section: String) String -> {
    loop parent in parents {
        if parent.section == section -> return parent.parent
    }
    return ""
}

fn has_field(fields: [Field], section: String, key: String) Bool -> {
    loop field in fields {
        if field.section == section {
            if field.key == key -> return true
        }
    }
    return false
}

fn field_value(fields: [Field], section: String, key: String) String -> {
    loop field in fields {
        if field.section == section {
            if field.key == key -> return field.value
        }
    }
    return ""
}

fn run() {
    path :: process.argv().get(1) ?? panic("missing path")
    content :: files.read(path) ?? panic("read failed")
    sections := [String]{}
    parents := [Parent]{}
    fields := [Field]{}
    current := ""

    loop raw in content.lines() {
        line :: ~(raw.trim())
        if line.is_empty() -> next
        if line.contains("[") {
            header_parts :: text.splitn(line, "[", 2)
            body :: header_parts.get(1) ?? panic("malformed section")
            name_parts :: text.splitn(body, "]", 2)
            name :: name_parts.get(0) ?? panic("malformed section")
            sections.push(name)
            current = name
        } else {
            pieces :: text.splitn(line, "=", 2)
            key := pieces.get(0) ?? panic("malformed field")
            value_part :: pieces.get(1) ?? panic("malformed field")
            key = ~(key.trim())
            quoted :: ~(value_part.trim())
            value_parts :: text.splitn(quoted, "\"", 3)
            value :: value_parts.get(1) ?? panic("malformed value")
            if key == "inherits" {
                parents.push(Parent{section: current, parent: value})
            } else {
                if has_field(fields, current, key) -> panic("duplicate field {key} in section {current}")
                fields.push(Field{section: current, key: key, value: value})
            }
        }
    }

    output := [String]{}
    loop section in sections {
        parent :: parent_for(parents, section)
        if parent.is_empty() {
            loop field in fields {
                if field.section == section -> output.push("{section}.{field.key}={field.value}")
            }
        } else {
            loop inherited in fields {
                if inherited.section == parent {
                    if has_field(fields, section, inherited.key) {
                        value :: field_value(fields, section, inherited.key)
                        output.push("{section}.{inherited.key}={value}")
                    } else {
                        output.push("{section}.{inherited.key}={inherited.value}")
                    }
                }
            }
            loop field in fields {
                if field.section == section {
                    if !has_field(fields, parent, field.key) -> output.push("{section}.{field.key}={field.value}")
                }
            }
        }
    }
    loop line in output {
        print(line)
    }
}
